// ECRÃ: LOGIN (escolha de perfil)
// ============================================================
function LoginScreen({ nav, onLogin }) {
  const [perfil, setPerfil] = useState('utente'); // utente | cuidador | profissional
  const [id, setId]     = useState('');           // nº utente (utente/cuidador) ou email (profissional)
  const [pass, setPass] = useState('');
  const isProf = perfil === 'profissional';
  const isCuidador = perfil === 'cuidador';

  const submit = () => {
    if (!id || !pass) { Alert.alert('Atenção', 'Por favor preencha os dois campos para entrar.'); return; }
    onLogin({
      email: id,
      nome: isProf ? 'Dra. Helena Marques' : (isCuidador ? 'Ana (filha)' : 'Maria Santos'),
      tipo: perfil,
    });
  };

  return (
    <SafeAreaView style={S.flexBg}>
      <Header title="" onBack={() => nav('welcome')} />
      <ScrollView contentContainerStyle={S.authScroll}>
        {/* Logo */}
        <View style={S.authLogoWrap}>
          <LogoCarePath size={130} />
        </View>

        {/* Toggle de perfil: utente / cuidador / profissional */}
        <View style={S.authToggle}>
          <TouchableOpacity onPress={() => setPerfil('utente')}
            accessibilityRole="button" accessibilityLabel="Entrar como utente"
            style={[S.tabBtn, perfil === 'utente' && S.tabBtnActive]}>
            <Text style={[S.tabBtnTxt, perfil === 'utente' && S.white]}>👤 Utente</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={() => setPerfil('cuidador')}
            accessibilityRole="button" accessibilityLabel="Entrar como cuidador"
            style={[S.tabBtn, perfil === 'cuidador' && S.tabBtnActive]}>
            <Text style={[S.tabBtnTxt, perfil === 'cuidador' && S.white]}>🤝 Cuidador</Text>
          </TouchableOpacity>
          <TouchableOpacity onPress={() => setPerfil('profissional')}
            accessibilityRole="button" accessibilityLabel="Entrar como profissional"
            style={[S.tabBtn, perfil === 'profissional' && S.tabBtnActive]}>
            <Text style={[S.tabBtnTxt, perfil === 'profissional' && S.white]}>🩺 Profiss.</Text>
          </TouchableOpacity>
        </View>

        {isProf ? (
          <>
            <Field label="EMAIL" value={id} onChange={setId}
              placeholder="email@instituicao.pt" keyboard="email-address" />
            <Field label="PALAVRA-PASSE" value={pass} onChange={setPass}
              placeholder="Palavra-passe" secure />
            <PrimaryBtn label="Entrar" onPress={submit} style={S.mt12} />
          </>
        ) : (
          <>
            <Field
              label={isCuidador ? 'NÚMERO DE UTENTE DE QUEM ACOMPANHA' : 'NÚMERO DE UTENTE (SNS)'}
              value={id} onChange={setId} placeholder="Ex: 123456789" keyboard="numeric" />
            <Field label="PALAVRA-PASSE" value={pass} onChange={setPass}
              placeholder="A sua palavra-passe" secure />
            <PrimaryBtn label="Entrar" onPress={submit} style={S.mt12} />
            <View style={S.loginHelp}>
              <Text style={S.loginHelpTitle}>
                {isCuidador ? 'Está a acompanhar um familiar' : 'Precisa de ajuda para entrar?'}
              </Text>
              <Text style={S.loginHelpTxt}>
                {isCuidador
                  ? 'Como cuidador, pode ver os dados, registar sinais e sintomas, e receber os alertas da pessoa que acompanha. Use o número de utente (SNS) dela.'
                  : 'Pode pedir a um familiar ou ao seu cuidador para o ajudar. Na sua unidade de saúde (USF) também o podem ajudar a aceder.'}
              </Text>
            </View>
          </>
        )}

        <TouchableOpacity onPress={() => nav('register')} style={S.authLink}>
          <Text style={S.authLinkTxt}>
            Não tem conta? <Text style={S.authLinkStrong}>Criar</Text>
          </Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
}

// ============================================================
// ECRÃ: REGISTO
// ============================================================
function RegisterScreen({ nav, onLogin }) {
  const [nome, setNome]   = useState('');
  const [email, setEmail] = useState('');
  const [pass, setPass]   = useState('');

  const submit = () => {
    if (!nome || !email || !pass) { Alert.alert('Erro', 'Preencha todos os campos'); return; }
    if (pass.length < 6)            { Alert.alert('Erro', 'Mínimo 6 caracteres'); return; }
    onLogin({ email, nome, tipo: 'utente' });
  };

  return (
    <SafeAreaView style={S.flexBg}>
      <Header title="Criar conta" onBack={() => nav('welcome')} />
      <ScrollView contentContainerStyle={S.regScroll}>
        <Field label="NOME COMPLETO" value={nome} onChange={setNome} placeholder="O seu nome" />
        <Field label="EMAIL" value={email} onChange={setEmail} placeholder="email@exemplo.pt" keyboard="email-address" />
        <Field label="PALAVRA-PASSE" value={pass} onChange={setPass} placeholder="Mínimo 6 caracteres" secure />
        <PrimaryBtn label="Criar conta" onPress={submit} style={S.mt8} />
        <Text style={S.regNote}>
          O registo de profissionais é feito pela instituição.
        </Text>
      </ScrollView>
    </SafeAreaView>
  );
}

