function QuickAction({ icon, label, onPress }) {
  return (
    <TouchableOpacity onPress={onPress} activeOpacity={0.75} style={S.quickAction}>
      <Text style={S.quickIcon}>{icon}</Text>
      <Text style={S.quickLabel}>{label}</Text>
    </TouchableOpacity>
  );
}

function MetricMini({ label, value, unit, color }) {
  return (
    <View style={[S.card, S.metricMini]}>
      <Text style={S.metricLabel}>{label}</Text>
      <Text style={[S.metricValue, { color }]}>{value}</Text>
      {unit ? <Text style={S.metricUnit}>{unit}</Text> : null}
    </View>
  );
}

// ============================================================
// VISTA UTENTE: REGISTAR SINAIS VITAIS
// ============================================================
function RegistoVitaisScreen({ nav, registos, setRegistos }) {
  const last = registos[0] || {};
  const [spo2, setSpo2] = useState(String(last.spo2 || 95));
  const [fc, setFc] = useState(String(last.fc || 75));
  const [taSis, setTaSis] = useState(String(last.ta_sis || 130));
  const [taDia, setTaDia] = useState(String(last.ta_dia || 80));
  const [peso, setPeso] = useState(String(last.peso || 70));

  const guardar = () => {
    // Validação de intervalos clínicos plausíveis
    const v = {
      spo2: parseInt(spo2), fc: parseInt(fc),
      ta_sis: parseInt(taSis), ta_dia: parseInt(taDia), peso: parseFloat(peso),
    };
    const erros = [];
    if (isNaN(v.spo2) || v.spo2 < 50 || v.spo2 > 100) erros.push('SpO₂ deve estar entre 50 e 100%');
    if (isNaN(v.fc) || v.fc < 30 || v.fc > 220) erros.push('FC deve estar entre 30 e 220 bpm');
    if (isNaN(v.ta_sis) || v.ta_sis < 60 || v.ta_sis > 260) erros.push('TA sistólica deve estar entre 60 e 260');
    if (isNaN(v.ta_dia) || v.ta_dia < 30 || v.ta_dia > 160) erros.push('TA diastólica deve estar entre 30 e 160');
    if (v.ta_sis <= v.ta_dia) erros.push('A sistólica tem de ser maior que a diastólica');
    if (isNaN(v.peso) || v.peso < 20 || v.peso > 300) erros.push('Peso deve estar entre 20 e 300 kg');

    if (erros.length) {
      Alert.alert('Valores fora do esperado', erros.join('\n'));
      return;
    }

    const novo = { ...last, ...v, ts: new Date().toISOString() };
    setRegistos([novo, ...registos]);
    Alert.alert('Guardado', 'Sinais vitais registados com sucesso', [{ text: 'OK', onPress: () => nav('home') }]);
  };

  return (
    <SafeAreaView style={S.flexBg}>
      <Header title="Sinais vitais" onBack={() => nav('home')} />
      <ScrollView contentContainerStyle={S.formScroll}>
        <Text style={[S.label, S.mb12]}>OXIGENAÇÃO E FREQUÊNCIA</Text>
        <View style={S.row10}>
          <View style={S.flex1}>
            <Field label="SpO₂ (%)" value={spo2} onChange={setSpo2} keyboard="numeric" />
          </View>
          <View style={S.flex1}>
            <Field label="FC (bpm)" value={fc} onChange={setFc} keyboard="numeric" />
          </View>
        </View>

        <Text style={[S.label, S.labelGap]}>TENSÃO ARTERIAL</Text>
        <View style={S.row10}>
          <View style={S.flex1}>
            <Field label="SISTÓLICA" value={taSis} onChange={setTaSis} keyboard="numeric" />
          </View>
          <View style={S.flex1}>
            <Field label="DIASTÓLICA" value={taDia} onChange={setTaDia} keyboard="numeric" />
          </View>
        </View>

        <Text style={[S.label, S.labelGap]}>BIOMETRIA</Text>
        <Field label="PESO (kg)" value={peso} onChange={setPeso} keyboard="numeric" />

        <PrimaryBtn label="Guardar registo" onPress={guardar} style={S.mt20} />
      </ScrollView>
    </SafeAreaView>
  );
}

// ============================================================
// VISTA UTENTE: ESCALAS mMRC + CAT
// ============================================================
function EscalasScreen({ nav, registos, setRegistos }) {
  const last = registos[0] || {};
  const [mmrc, setMmrc] = useState(last.mmrc || 0);
  const [cat, setCat] = useState(last.cat_items || [0,0,0,0,0,0,0,0]);

  const CAT_ITEMS = [
    'Nunca tusso  ↔  Estou sempre a tossir',
    'Sem expetoração  ↔  Cheio de expetoração',
    'Sem aperto no peito  ↔  Muito aperto no peito',
    'Sem falta de ar a subir uma rampa  ↔  Muita falta de ar',
    'Sem limitação em casa  ↔  Muito limitado em casa',
    'Confiante para sair  ↔  Sem confiança para sair',
    'Durmo bem  ↔  Não durmo bem',
    'Muita energia  ↔  Nenhuma energia',
  ];

  const MMRC_LABELS = [
    '0 - Só com exercício intenso',
    '1 - Falta de ar ao apressar-me',
    '2 - Mais lento que outros da mesma idade',
    '3 - Paro para respirar após 100m',
    '4 - Falta de ar para sair de casa',
  ];

  const catTotal = cat.reduce((a, b) => a + b, 0);
  const setCatItem = (i, v) => { const next = [...cat]; next[i] = v; setCat(next); };

  const guardar = () => {
    const novo = {
      ...last,
      mmrc,
      cat: catTotal,
      cat_items: cat,
      ts: new Date().toISOString(),
    };
    setRegistos([novo, ...registos]);
    Alert.alert('Guardado', `mMRC: ${mmrc}\nCAT: ${catTotal} pontos`, [{ text: 'OK', onPress: () => nav('home') }]);
  };

  return (
    <SafeAreaView style={S.x8d5d23}>
      <Header title="Como me sinto" onBack={() => nav('home')} />
      <ScrollView contentContainerStyle={S.xadd871}>
        <Card style={S.xad064e}>
          <Text style={[S.label, { marginBottom: 10 }]}>FALTA DE AR (mMRC)</Text>
          <Text style={S.x18bca1}>
            Escolha a opção que melhor descreve a sua falta de ar:
          </Text>
          {MMRC_LABELS.map((lbl, i) => (
            <TouchableOpacity key={i} onPress={() => setMmrc(i)}
              style={[S.optionRow, mmrc === i && S.optionRowActive]}>
              <View style={[S.radio, mmrc === i && { backgroundColor: T.teal, borderColor: T.teal }]}>
                {mmrc === i ? <View style={S.x975d67} /> : null}
              </View>
              <Text style={{ color: mmrc === i ? T.teal : T.white2, fontSize: 13, flex: 1, fontWeight: mmrc === i ? '700' : '400' }}>{lbl}</Text>
            </TouchableOpacity>
          ))}
        </Card>

        <Card>
          <View style={S.xc1a98d}>
            <Text style={S.label}>SINTOMAS NO DIA A DIA (CAT)</Text>
            <Badge label={`Total: ${catTotal}`} color={catTotal >= 20 ? T.red : catTotal >= 10 ? T.yellow : T.green} />
          </View>
          <Text style={S.x18bca1}>
            0 = nada / 5 = muito. Para cada afirmação, escolha o nível:
          </Text>
          {CAT_ITEMS.map((item, i) => (
            <View key={i} style={S.x64b117}>
              <Text style={S.xf7b054}>{item}</Text>
              <View style={S.x97a585}>
                {[0,1,2,3,4,5].map(n => (
                  <TouchableOpacity key={n} onPress={() => setCatItem(i, n)}
                    style={[S.scaleBtn, { aspectRatio: 1.1 }, cat[i] === n && S.scaleBtnActive]}>
                    <Text style={[S.scaleBtnTxt, { fontSize: 13 }, cat[i] === n && { color: '#fff' }]}>{n}</Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          ))}
        </Card>

        <PrimaryBtn label="Guardar escalas" onPress={guardar} style={S.xa84ff1} />
      </ScrollView>
    </SafeAreaView>
  );
}

// ============================================================
// VISTA UTENTE: MEDICAÇÃO (adesão)
// ============================================================
function MedicacaoScreen({ nav, medicacao, setMedicacao }) {
  const toggleTomada = (idx) => {
    const next = [...medicacao];
    next[idx] = { ...next[idx], tomadoHoje: !next[idx].tomadoHoje };
    setMedicacao(next);
  };

  const aderencia = Math.round((medicacao.filter(m => m.tomadoHoje).length / medicacao.length) * 100);

  return (
    <SafeAreaView style={S.x8d5d23}>
      <Header title="Medicação" onBack={() => nav('home')} />
      <ScrollView contentContainerStyle={S.xadd871}>
        <Card accent style={S.x03f105}>
          <Text style={S.label}>ADESÃO DE HOJE</Text>
          <Text style={{ color: aderencia === 100 ? T.green : aderencia >= 50 ? T.yellow : T.red, fontSize: 42, fontWeight: '900', marginTop: 4 }}>
            {aderencia}%
          </Text>
          <Text style={S.xa87ee8}>
            {medicacao.filter(m => m.tomadoHoje).length} de {medicacao.length} medicamentos
          </Text>
        </Card>

        <Text style={[S.label, { marginBottom: 8 }]}>O SEU PLANO TERAPÊUTICO</Text>
        {medicacao.map((m, i) => (
          <TouchableOpacity key={i} onPress={() => toggleTomada(i)} activeOpacity={0.75}
            style={[S.card, { flexDirection: 'row', alignItems: 'center', marginBottom: 10 }]}>
            <View style={{ width: 28, height: 28, borderRadius: 14, borderWidth: 2,
              borderColor: m.tomadoHoje ? T.teal : T.border2,
              backgroundColor: m.tomadoHoje ? T.teal : 'transparent',
              alignItems: 'center', justifyContent: 'center', marginRight: 12 }}>
              {m.tomadoHoje ? <Text style={S.xa8c375}>✓</Text> : null}
            </View>
            <View style={S.xd2dc0a}>
              <Text style={S.x956d8f}>{m.nome}</Text>
              <Text style={S.x6fa955}>{m.dose} • {m.horario}</Text>
            </View>
          </TouchableOpacity>
        ))}
      </ScrollView>
    </SafeAreaView>
  );
}

// ============================================================
// VISTA UTENTE: SINTOMAS / NOTAS
// ============================================================
function SintomasScreen({ nav, sintomas, setSintomas }) {
  const [tosse, setTosse] = useState(1);
  const [expetoracao, setExp] = useState(1);
  const [passos, setPassos] = useState('3500');
  const [nota, setNota] = useState('');

  const guardar = () => {
    const nPassos = parseInt(passos) || 0;
    if (nPassos < 0 || nPassos > 100000) {
      Alert.alert('Valor fora do esperado', 'O número de passos deve estar entre 0 e 100000.');
      return;
    }
    const novo = {
      tosse, expetoracao,
      passos: nPassos,
      nota,
      ts: new Date().toISOString(),
    };
    setSintomas([novo, ...sintomas]);
    Alert.alert('Registado', 'Notas guardadas. A sua equipa terá acesso.', [{ text: 'OK', onPress: () => nav('home') }]);
  };

  return (
    <SafeAreaView style={S.x8d5d23}>
      <Header title="Os meus sintomas" onBack={() => nav('home')} />
      <ScrollView contentContainerStyle={S.xadd871}>
        <Text style={[S.label, { marginBottom: 12 }]}>SINTOMAS RESPIRATÓRIOS (0-5)</Text>
        <ScaleRow label="Tosse" value={tosse} onChange={setTosse} />
        <ScaleRow label="Expetoração" value={expetoracao} onChange={setExp} />

        <Text style={[S.label, { marginTop: 8, marginBottom: 12 }]}>ATIVIDADE FÍSICA</Text>
        <Field label="PASSOS HOJE" value={passos} onChange={setPassos} keyboard="numeric" />

        <Text style={[S.label, { marginTop: 8, marginBottom: 12 }]}>NOTAS PARA A SUA EQUIPA</Text>
        <Field
          value={nota} onChange={setNota}
          placeholder="Escreva como se sente, dúvidas, mudanças..."
          multiline
        />

        <PrimaryBtn label="Enviar à equipa" onPress={guardar} style={S.x7892f0} />
      </ScrollView>
    </SafeAreaView>
  );
}

