// ============================================================
// VISTA UTENTE: TRIAGEM IA — Precisa de ajuda já
// Fluxo: perguntas guiadas → algoritmo → encaminhamento
// ============================================================
// ============================================================
// PEDIR CONSULTA (o utente PEDE; a equipa confirma)
// O utente escolhe a especialidade e contacta: liga ou envia pedido.
// O pedido fica pendente de confirmação — não marca a consulta sozinho.
// ============================================================

function PedirConsultaScreen({ nav, user, consultas, setConsultas, chatMensagens, setChatMensagens }) {
  const [escolhido, setEscolhido] = useState(null);

  const ligar = (membro) => {
    const tel = (membro.spec.includes('Família') && user?.medicoFamilia?.tel)
      ? user.medicoFamilia.tel
      : (user?.usfTel || '253 000 000');
    const num = tel.replace(/\s/g, '');
    Linking.openURL(`tel:${num}`).catch(() =>
      Alert.alert('Não foi possível ligar', `Telefone: ${tel}`));
  };

  const enviarPedido = (membro) => {
    // 1. regista um PEDIDO de consulta (pendente de confirmação pela equipa)
    if (setConsultas) {
      const data = diaUtilDaqui(MOTOR_CONFIG.diasRiscoModerado);
      setConsultas((prev) => [...(prev || []), {
        utenteId: user?.id || 'u1', utenteNome: user?.nome || 'Utente',
        especialistaId: 'p' + membro.id,
        id: 'pedido_' + Date.now(), data: data.toISOString().split('T')[0], hora: '—',
        motivo: `Pedido de consulta · ${membro.spec}`, estado: 'sugerida',
        marcadoPor: 'Pedido do utente', origem: 'pedido_consulta', timestamp: Date.now(),
      }]);
    }
    // 2. deixa uma mensagem no chat clínico para a equipa ver
    if (setChatMensagens) {
      setChatMensagens((prev) => [...(prev || []), {
        id: 'm' + Date.now(), autor: 'utente', nome: user?.nome || 'Utente',
        texto: `Olá. Gostaria de pedir uma consulta de ${membro.spec}, por favor.`,
        ts: new Date().toISOString(),
      }]);
    }
    Alert.alert('Pedido enviado',
      `O seu pedido de consulta de ${membro.spec} foi enviado à equipa. Vão analisá-lo e contactá-lo para confirmar a marcação.`,
      [{ text: 'OK', onPress: () => nav('home') }]);
  };

  return (
    <SafeAreaView style={S.flexBg}>
      <Header title="Pedir consulta" onBack={() => nav('home')} />
      <ScrollView contentContainerStyle={S.formScroll}>
        <Text style={[S.label, S.mb12]}>QUAL A CONSULTA QUE PRECISA?</Text>
        {EQUIPA_DPOC.map((m) => {
          const sel = escolhido === m.id;
          return (
            <TouchableOpacity key={m.id} activeOpacity={0.8} onPress={() => setEscolhido(sel ? null : m.id)}
              accessibilityRole="button" accessibilityLabel={`Consulta de ${m.spec}`}
              style={[S.specRow, sel && S.specRowSel]}>
              <View style={[S.specIcon, { backgroundColor: m.cor + '20' }]}>
                <Text style={S.specIconTxt}>{m.icon}</Text>
              </View>
              <View style={S.flex1}>
                <Text style={S.specName}>{m.spec}</Text>
                <Text style={S.specSub}>{m.nome}</Text>
              </View>
              <Text style={[S.specChevron, sel && { color: T.teal }]}>{sel ? '▾' : '›'}</Text>
            </TouchableOpacity>
          );
        })}

        {escolhido ? (
          <View style={S.pedirAcoes}>
            {(() => {
              const m = EQUIPA_DPOC.find(x => x.id === escolhido);
              return (
                <>
                  <Text style={S.pedirComo}>Como prefere contactar para a consulta de {m.spec}?</Text>
                  <PrimaryBtn label="📨 Enviar pedido à equipa" onPress={() => enviarPedido(m)} />
                  <TouchableOpacity onPress={() => ligar(m)} activeOpacity={0.8} style={S.ligarBtn}
                    accessibilityRole="button" accessibilityLabel="Ligar à equipa">
                    <Text style={S.ligarTxt}>📞 Ligar à equipa</Text>
                  </TouchableOpacity>
                </>
              );
            })()}
          </View>
        ) : null}

        <Text style={S.assistDisclaimer}>
          O seu pedido é enviado à equipa, que confirma a marcação. Não é uma consulta marcada automaticamente.
        </Text>
      </ScrollView>
    </SafeAreaView>
  );
}

