// ============================================================
// ASSISTENTE DE ENCAMINHAMENTO (agente conversacional)
// Baseado no PROTOCOLO clínico (regras seguras), não em IA generativa.
// Conversa de forma acessível, encaminha de forma conservadora e
// SINALIZA à equipa — nunca decide clinicamente.
// ============================================================

const ASSISTENTE_PERGUNTAS = [
  { id: 'resp', txt: 'Olá! Sou o assistente do CarePath. Vou fazer algumas perguntas simples para o ajudar a chegar ao sítio certo. Como está a sua respiração hoje?',
    ops: [
      { label: 'Muito pior que o normal', peso: 3 },
      { label: 'Um pouco pior', peso: 1 },
      { label: 'Como de costume', peso: 0 },
    ] },
  { id: 'fala', txt: 'Consegue dizer uma frase inteira sem parar para respirar?',
    ops: [
      { label: 'Sim, sem dificuldade', peso: 0 },
      { label: 'Com alguma dificuldade', peso: 2 },
      { label: 'Não consigo', peso: 0, alarme: true },
    ] },
  { id: 'azul', txt: 'Reparou nos lábios, língua ou unhas com cor azulada/arroxeada?',
    ops: [
      { label: 'Não', peso: 0 },
      { label: 'Sim', peso: 0, alarme: true },
    ] },
  { id: 'peito', txt: 'Sente dor no peito ou um aperto forte que não passa?',
    ops: [
      { label: 'Não', peso: 0 },
      { label: 'Sim', peso: 0, alarme: true },
    ] },
  { id: 'exp', txt: 'A tosse ou a expetoração mudaram (mais quantidade, cor diferente, ou febre)?',
    ops: [
      { label: 'Não', peso: 0 },
      { label: 'Um pouco', peso: 1 },
      { label: 'Sim, bastante', peso: 2 },
    ] },
];

function avaliarEncaminhamento(respostas) {
  const temAlarme = respostas.some(r => r.alarme);
  const pontos = respostas.reduce((s, r) => s + (r.peso || 0), 0);
  if (temAlarme || pontos >= 5) {
    return { nivel: 'urgencia', cor: T.red, icon: '🚨',
      titulo: 'Procure ajuda agora',
      msg: 'Pelo que me disse, deve ser avaliado com urgência. Ligue 112 ou vá à urgência mais próxima. Não espere.' };
  }
  if (pontos >= 2) {
    return { nivel: 'equipa', cor: T.yellow, icon: '⚠️',
      titulo: 'Vamos avisar a sua equipa',
      msg: 'Os seus sintomas justificam que a equipa o veja em breve. Vou avisá-la por si — vão rever a sua situação e contactá-lo.' };
  }
  return { nivel: 'estavel', cor: T.green, icon: '✓',
    titulo: 'Parece estável',
    msg: 'Não encontrei sinais de alarme. Continue a registar como se sente. Se piorar, fale comigo outra vez ou contacte a equipa.' };
}

function AssistenteScreen({ nav, user, consultas, setConsultas }) {
  const [passo, setPasso] = useState(0);
  const [respostas, setRespostas] = useState([]);
  const terminado = passo >= ASSISTENTE_PERGUNTAS.length;
  const resultado = terminado ? avaliarEncaminhamento(respostas) : null;

  const responder = (op) => { setRespostas([...respostas, op]); setPasso(passo + 1); };

  const agir = () => {
    if (resultado.nivel === 'urgencia') {
      Alert.alert('📞 112', 'A ligar para o INEM. Em caso real, ligaria automaticamente. Se não conseguir, peça ajuda a alguém por perto.');
    } else if (resultado.nivel === 'equipa') {
      if (setConsultas) {
        const data = diaUtilDaqui(MOTOR_CONFIG.diasRiscoModerado);
        setConsultas((prev) => [...(prev || []), {
          utenteId: user?.id || 'u1', utenteNome: user?.nome || 'Utente', especialistaId: 'p2',
          id: 'assist_' + Date.now(), data: data.toISOString().split('T')[0], hora: '11:00',
          motivo: 'Pedido via assistente · sinais a vigiar', estado: 'sugerida',
          marcadoPor: 'Pedido via assistente (utente)', origem: 'assistente_utente', timestamp: Date.now(),
        }]);
      }
      Alert.alert('A sua equipa foi avisada', 'A equipa vai rever a sua situação e contactá-lo. Obrigado por usar o assistente.');
    } else {
      nav('registo');
    }
  };

  const reiniciar = () => { setPasso(0); setRespostas([]); };

  return (
    <SafeAreaView style={S.flexBg}>
      <Header title="💬 Assistente" onBack={() => nav('home')} />
      <ScrollView contentContainerStyle={S.assistScroll}>
        {ASSISTENTE_PERGUNTAS.slice(0, passo + (terminado ? 0 : 1)).map((p, i) => (
          <View key={p.id}>
            <View style={S.bubbleBot}><Text style={S.bubbleBotTxt}>{p.txt}</Text></View>
            {respostas[i] ? (
              <View style={S.bubbleUser}><Text style={S.bubbleUserTxt}>{respostas[i].label}</Text></View>
            ) : null}
          </View>
        ))}

        {!terminado ? (
          <View style={S.assistOps}>
            {ASSISTENTE_PERGUNTAS[passo].ops.map((op) => (
              <TouchableOpacity key={op.label} onPress={() => responder(op)} activeOpacity={0.8}
                accessibilityRole="button" accessibilityLabel={op.label} style={S.assistOpBtn}>
                <Text style={S.assistOpTxt}>{op.label}</Text>
              </TouchableOpacity>
            ))}
          </View>
        ) : (
          <View>
            <View style={[S.assistResult, { borderLeftColor: resultado.cor }]}>
              <Text style={S.assistResultIcon}>{resultado.icon}</Text>
              <Text style={S.assistResultTitle}>{resultado.titulo}</Text>
              <Text style={S.assistResultMsg}>{resultado.msg}</Text>
            </View>
            <PrimaryBtn
              label={resultado.nivel === 'urgencia' ? '📞 Ligar 112' : resultado.nivel === 'equipa' ? 'Avisar a minha equipa' : 'Registar como me sinto'}
              onPress={agir} />
            <TouchableOpacity onPress={reiniciar} style={S.assistRestart}>
              <Text style={S.assistRestartTxt}>↻ Começar de novo</Text>
            </TouchableOpacity>
            <Text style={S.assistDisclaimer}>
              Este assistente ajuda a orientar, mas não substitui a sua equipa de saúde. Em caso de dúvida ou emergência, ligue sempre 112.
            </Text>
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

function TriagemIAScreen({ nav, user, registos, consultas, setConsultas }) {
  const [passo, setPasso] = useState(0);   // 0..3 = perguntas, 4 = resultado
  const [respostas, setRespostas] = useState({});

  const PERGUNTAS = [
    {
      id: 'dispneia',
      pergunta: 'Como está a sua falta de ar agora?',
      opcoes: [
        { v: 0, l: 'Igual ao habitual',                  cor: T.green  },
        { v: 1, l: 'Um pouco pior que o habitual',       cor: T.yellow },
        { v: 2, l: 'Muito pior — sinto-me sufocado(a)',  cor: T.red    },
      ],
    },
    {
      id: 'expetoracao',
      pergunta: 'A sua expetoração mudou?',
      opcoes: [
        { v: 0, l: 'Igual ao habitual',                       cor: T.green  },
        { v: 1, l: 'Mais quantidade ou mais espessa',         cor: T.yellow },
        { v: 2, l: 'Cor amarela/verde ou com sangue',         cor: T.red    },
      ],
    },
    {
      id: 'febre',
      pergunta: 'Tem febre, calafrios ou suores?',
      opcoes: [
        { v: 0, l: 'Não',                                     cor: T.green  },
        { v: 1, l: 'Sinto-me quente mas não medi a temperatura', cor: T.yellow },
        { v: 2, l: 'Sim, com mais de 38°C',                   cor: T.red    },
      ],
    },
    {
      id: 'sintomas_graves',
      pergunta: 'Tem algum destes sintomas agora?',
      opcoes: [
        { v: 0, l: 'Nenhum dos abaixo',                                       cor: T.green },
        { v: 1, l: 'Inchaço nas pernas ou cansaço extremo',                   cor: T.yellow },
        { v: 2, l: 'Dor no peito · lábios/dedos azulados · confusão',         cor: T.red },
      ],
    },
  ];

  const responder = (id, v) => {
    setRespostas({ ...respostas, [id]: v });
    setPasso(passo + 1);
  };

  // Algoritmo de triagem — soma ponderada
  const calcular = () => {
    const ultimo = registos?.[0] || {};
    let score = 0;
    Object.values(respostas).forEach(v => { score += v; });
    // Adiciona sinais vitais ao score
    if (ultimo.spo2 && ultimo.spo2 < 90) score += 3;
    else if (ultimo.spo2 && ultimo.spo2 < 92) score += 2;
    if (ultimo.fc && ultimo.fc > 110) score += 1;

    // Decisão de encaminhamento
    if (respostas.sintomas_graves === 2 || (ultimo.spo2 && ultimo.spo2 < 88) || score >= 7) {
      return {
        nivel: 'URGENTE',
        cor: T.red,
        icon: '🚨',
        titulo: 'Recomenda-se ir à urgência',
        mensagem: 'Os sintomas que descreveu sugerem necessidade de avaliação hospitalar imediata. Ligue 112 ou desloque-se à urgência mais próxima.',
        acoes: [
          { label: '📞 Ligar 112', tipo: 'urgencia', cor: T.red },
          { label: '🏥 Hospital de Braga · Urgência', tipo: 'morada', cor: T.tealDark },
          { label: '📅 Avisar a minha equipa', tipo: 'agenda', nivelRisco: 'alto', cor: T.teal },
          { label: 'Notificar a minha equipa', tipo: 'notificar', cor: T.tealDark },
        ],
        encaminhamento: 'Urgência Hospital de Braga',
      };
    }
    if (score >= 4) {
      return {
        nivel: 'PRIORITÁRIO',
        cor: T.yellow,
        icon: '⚠️',
        titulo: 'Contacte a sua equipa de proximidade hoje',
        mensagem: 'Os sintomas justificam avaliação clínica nas próximas horas. Vamos avisar o seu médico/enfermeiro de família para contacto rápido.',
        acoes: [
          { label: `📞 Ligar ${user?.medicoFamilia?.nome || 'Médico de família'}`, tipo: 'medico', cor: T.tealDark },
          { label: `📞 Ligar ${user?.enfFamilia?.nome    || 'Enfermeiro de família'}`, tipo: 'enf', cor: T.tealDark },
          { label: '📅 Avisar a minha equipa', tipo: 'agenda', nivelRisco: 'moderado', cor: T.teal },
        ],
        encaminhamento: user?.usf || 'USF',
      };
    }
    return {
      nivel: 'NÃO URGENTE',
      cor: T.green,
      icon: '✓',
      titulo: 'Sem sinais de exacerbação aguda',
      mensagem: 'Os seus sintomas parecem estáveis. Continue a registar os sinais vitais e os sintomas. Se piorar, repita esta triagem.',
      acoes: [
        { label: 'Registar sinais vitais agora', tipo: 'registar', cor: T.teal },
        { label: 'Mensagem ao enfermeiro de família', tipo: 'msg', cor: T.tealDark },
      ],
      encaminhamento: 'Auto-monitorização',
    };
  };

  const handleAcao = (acao) => {
    if (acao.tipo === 'urgencia')    Alert.alert('📞 112', 'A ligar para o INEM. Em caso real, ligará automaticamente.');
    else if (acao.tipo === 'morada') Alert.alert('🏥 Hospital de Braga', 'Sete Fontes — São Victor, 4710-243 Braga\nUrgência: aberta 24h');
    else if (acao.tipo === 'medico') Alert.alert('📞 Médico de família', `A ligar para ${user?.medicoFamilia?.nome}\n${user?.medicoFamilia?.tel}`);
    else if (acao.tipo === 'enf')    Alert.alert('📞 Enfermeiro de família', `A ligar para ${user?.enfFamilia?.nome}\n${user?.enfFamilia?.tel}`);
    else if (acao.tipo === 'notificar') Alert.alert('✓ Equipa notificada', 'O Dr. António Silva (Médico de família) e a Dra. Helena Marques (Pneumologia) foram alertados.');
    else if (acao.tipo === 'consulta')  Alert.alert('Consulta urgente', `Pedido enviado à ${user?.usf || 'USF'}. Receberá contacto em <4h.`);
    else if (acao.tipo === 'agenda') {
      // GOVERNANÇA: o utente apenas SINALIZA. A decisão clínica de antecipar
      // a consulta cabe à equipa. Por isso, criamos um PEDIDO pendente de
      // confirmação e não expomos ao utente a mecânica do motor (datas,
      // limites de segurança, justificação técnica) — isso é para o profissional.
      const decisao = decidirAgenda({ nivel: acao.nivelRisco }, user);
      if (decisao.consulta && setConsultas) {
        const pedido = {
          ...decisao.consulta,
          estado: 'sugerida',                 // pendente de confirmação pela equipa
          marcadoPor: 'Pedido via triagem (utente)',
          origem: 'triagem_utente',
          justificacao: decisao.justificacao, // guardado para o PROFISSIONAL ver
        };
        setConsultas((prev) => [...(prev || []), pedido]);
      }
      // Mensagem simples e tranquilizadora — sem informação privilegiada
      Alert.alert('A sua equipa foi avisada',
        'A equipa vai rever a sua situação e contactá-lo para ajustar a consulta, se for necessário.');
    }
    else if (acao.tipo === 'registar')  { nav('registo'); return; }
    else if (acao.tipo === 'msg')       Alert.alert('Mensagem enviada', 'O enfermeiro de família vai responder em breve.');
  };

  // RENDER
  if (passo < PERGUNTAS.length) {
    const p = PERGUNTAS[passo];
    return (
      <SafeAreaView style={S.x8d5d23}>
        <Header title="🤖 Triagem IA" onBack={() => passo === 0 ? nav('home') : setPasso(passo - 1)} />
        <ScrollView contentContainerStyle={S.xdc5e6d}>
          {/* Progresso */}
          <View style={S.x6cde9a}>
            {PERGUNTAS.map((_, i) => (
              <View key={i} style={{
                flex: 1, height: 4, borderRadius: 2,
                backgroundColor: i <= passo ? T.teal : T.border2,
              }} />
            ))}
          </View>

          <Text style={S.x9b43ec}>
            PERGUNTA {passo + 1} DE {PERGUNTAS.length}
          </Text>
          <Text style={S.x6cd182}>
            {p.pergunta}
          </Text>

          {p.opcoes.map((op, i) => (
            <TouchableOpacity key={i} onPress={() => responder(p.id, op.v)} activeOpacity={0.8}
              style={S.x15c1fc}>
              <View style={{ width: 12, height: 12, borderRadius: 6, backgroundColor: op.cor, marginRight: 12 }} />
              <Text style={S.x668eac}>{op.l}</Text>
              <Text style={S.x1c53cb}>›</Text>
            </TouchableOpacity>
          ))}

          <Text style={S.xec027d}>
            Esta triagem usa IA para orientar mas não substitui avaliação médica.{'\n'}Em emergência ligue sempre 112.
          </Text>
        </ScrollView>
      </SafeAreaView>
    );
  }

  // Resultado final
  const r = calcular();
  return (
    <SafeAreaView style={S.x8d5d23}>
      <Header title="🤖 Resultado da triagem" onBack={() => nav('home')} />
      <ScrollView contentContainerStyle={S.xdc5e6d}>
        {/* Card grande do resultado */}
        <View style={{
          backgroundColor: r.cor, borderRadius: 18, padding: 20, marginBottom: 16,
          shadowColor: r.cor, shadowOpacity: 0.25, shadowRadius: 12, shadowOffset: { width: 0, height: 4 }, elevation: 3,
        }}>
          <Text style={S.x97af76}>{r.icon}</Text>
          <Text style={S.x34acd3}>
            {r.nivel}
          </Text>
          <Text style={S.x25aef3}>
            {r.titulo}
          </Text>
          <Text style={{ color: 'rgba(255,255,255,0.95)', fontSize: 13, lineHeight: 19, marginTop: 8 }}>
            {r.mensagem}
          </Text>
        </View>

        {/* Encaminhamento */}
        <View style={S.x26fce6}>
          <Text style={S.xa7c96d}>➡️</Text>
          <View style={S.xd2dc0a}>
            <Text style={S.xf55a28}>ENCAMINHAR PARA</Text>
            <Text style={S.xaabbf9}>{r.encaminhamento}</Text>
          </View>
        </View>

        {/* Ações */}
        <Text style={[S.label, { marginBottom: 8 }]}>O QUE FAZER AGORA</Text>
        {r.acoes.map((a, i) => (
          <TouchableOpacity key={i} onPress={() => handleAcao(a)} activeOpacity={0.85}
            style={{
              backgroundColor: a.cor, borderRadius: 14, paddingVertical: 14, paddingHorizontal: 16,
              flexDirection: 'row', alignItems: 'center', marginBottom: 8,
            }}>
            <Text style={S.x6cab50}>{a.label}</Text>
            <Text style={S.x435c0d}>›</Text>
          </TouchableOpacity>
        ))}

        {/* Refazer triagem */}
        <TouchableOpacity onPress={() => { setPasso(0); setRespostas({}); }} activeOpacity={0.7}
          style={S.xb329d2}>
          <Text style={S.x377c2d}>↺ Refazer a triagem</Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
}

