// ============================================================
// VISTA UTENTE: AGENDA LONGITUDINAL (timeline central da app)
// ============================================================
function HistoricoScreen({ nav, registos, sintomas }) {
  const [filtro, setFiltro] = useState('todos'); // todos | consultas | registos | eventos

  // Constrói lista unificada de TODOS os eventos
  const eventos = useMemo(() => {
    const reg = registos.map(x => ({
      ts: x.ts, tipo: 'registo', dados: x,
    }));
    const sin = sintomas.map(x => ({
      ts: x.ts, tipo: 'sintoma', dados: x,
    }));
    const con = CONSULTAS_UTENTE.map(c => ({
      ts: c.ts, tipo: c.tipo, dados: c,
    }));
    return [...reg, ...sin, ...con].sort((a, b) => new Date(b.ts) - new Date(a.ts));
  }, [registos, sintomas]);

  const filtrados = eventos.filter(e => {
    if (filtro === 'todos') return true;
    if (filtro === 'consultas') return e.tipo === 'consulta' || e.tipo === 'consulta_futura';
    if (filtro === 'registos')  return e.tipo === 'registo' || e.tipo === 'sintoma';
    if (filtro === 'eventos')   return ['alerta_ia','exame','medicacao','exacerbacao','diagnostico'].includes(e.tipo);
    return true;
  });

  // Separa futuras de passadas
  const agora = Date.now();
  const futuras = filtrados.filter(e => new Date(e.ts).getTime() > agora);
  const passadas = filtrados.filter(e => new Date(e.ts).getTime() <= agora);

  // Estatísticas
  const totalConsultas = CONSULTAS_UTENTE.filter(c => c.tipo === 'consulta').length;
  const proxConsulta = CONSULTAS_UTENTE
    .filter(c => c.tipo === 'consulta_futura')
    .sort((a, b) => new Date(a.ts) - new Date(b.ts))[0];

  return (
    <SafeAreaView style={S.x8d5d23}>
      <Header title="O meu histórico" onBack={() => nav('home')} />

      {/* Resumo no topo */}
      <View style={S.x89ec2c}>
        <View style={S.x796443}>
          <Card style={S.x730103}>
            <Text style={S.xea54ae}>CONSULTAS</Text>
            <Text style={S.x69d6ff}>{totalConsultas}</Text>
            <Text style={S.x41a694}>12 meses</Text>
          </Card>
          <Card style={S.x730103}>
            <Text style={S.xea54ae}>REGISTOS</Text>
            <Text style={S.x2ac6aa}>{registos.length + sintomas.length}</Text>
            <Text style={S.x41a694}>seus</Text>
          </Card>
          <Card style={S.x730103}>
            <Text style={S.xea54ae}>EXACERB.</Text>
            <Text style={S.xc1126d}>1</Text>
            <Text style={S.x41a694}>12 meses</Text>
          </Card>
        </View>

        {/* Legenda de especialidades - mostra quem cuida do utente */}
        <View style={S.xe5e794}>
          <Text style={S.x9fabc0}>
            👥 EQUIPA QUE ME ACOMPANHA
          </Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false}>
            <View style={S.xb1c468}>
              {EQUIPA_DPOC.slice(0, 5).map(p => (
                <View key={p.id} style={{
                  flexDirection: 'row', alignItems: 'center',
                  backgroundColor: p.cor + '15',
                  paddingHorizontal: 8, paddingVertical: 4, borderRadius: 999,
                }}>
                  <View style={{
                    width: 6, height: 6, borderRadius: 3,
                    backgroundColor: p.cor, marginRight: 5,
                  }} />
                  <Text style={{ color: p.cor, fontSize: 10, fontWeight: '700' }}>
                    {p.spec.split(' ')[0]}
                  </Text>
                </View>
              ))}
            </View>
          </ScrollView>
        </View>

        {/* Filtros */}
        <ScrollView horizontal showsHorizontalScrollIndicator={false}
          contentContainerStyle={S.x28fbc5}>
          {[
            { id: 'todos',     label: 'Tudo' },
            { id: 'consultas', label: 'Consultas' },
            { id: 'registos',  label: 'Os meus registos' },
            { id: 'eventos',   label: 'Eventos clínicos' },
          ].map(f => (
            <TouchableOpacity key={f.id} onPress={() => setFiltro(f.id)}
              style={[S.pill, filtro === f.id && S.pillActive]}>
              <Text style={[S.pillTxt, filtro === f.id && { color: '#fff' }]}>{f.label}</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>

      <ScrollView contentContainerStyle={S.x1a5895}>
        {/* SECÇÃO: AGENDADAS */}
        {futuras.length > 0 ? (
          <>
            <View style={S.x1ffd09}>
              <View style={S.xcc86f6} />
              <Text style={[S.label, { marginBottom: 0 }]}>PRÓXIMAS CONSULTAS</Text>
            </View>
            {futuras.map((e, i) => <TimelineItem key={`f${i}`} evento={e} futura />)}
          </>
        ) : null}

        {/* SECÇÃO: HISTÓRICO */}
        <View style={S.xd3c5f6}>
          <View style={S.xd912e1} />
          <Text style={[S.label, { marginBottom: 0 }]}>HISTÓRICO</Text>
        </View>

        {passadas.length === 0 ? (
          <Card style={S.x79bc9a}>
            <Text style={S.xfc85b1}>📋</Text>
            <Text style={S.x77752b}>Sem eventos no filtro escolhido</Text>
          </Card>
        ) : (
          passadas.map((e, i) => <TimelineItem key={`p${i}`} evento={e} />)
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

// Item individual da timeline com linha vertical conectora
function TimelineItem({ evento, futura }) {
  const { tipo, ts, dados } = evento;
  const dt = new Date(ts);
  const dataFmt = dt.toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' });
  const horaFmt = dt.toLocaleTimeString('pt-PT', { hour: '2-digit', minute: '2-digit' });

  // Cor + ícone por tipo
  let cor = T.teal, icon = '📋', titulo = '', subtitulo = '';
  if (tipo === 'consulta_futura') {
    const pro = getProById(dados.profId);
    cor = T.teal; icon = '📅';
    titulo = dados.motivo;
    subtitulo = `${pro?.nome || ''} • ${dados.modalidade}`;
  } else if (tipo === 'consulta') {
    const pro = getProById(dados.profId);
    cor = pro?.cor || T.tealDark; icon = pro?.icon || '🩺';
    titulo = dados.motivo;
    subtitulo = pro?.nome || '';
  } else if (tipo === 'registo') {
    cor = T.teal; icon = '🫁';
    titulo = 'Sinais vitais registados';
    subtitulo = `SpO₂ ${dados.spo2}% • FC ${dados.fc}${dados.mmrc !== undefined ? ` • mMRC ${dados.mmrc}` : ''}`;
  } else if (tipo === 'sintoma') {
    cor = T.blue; icon = '📝';
    titulo = 'Notas / sintomas';
    subtitulo = `Tosse ${dados.tosse}/5 • Passos ${dados.passos}`;
  } else if (tipo === 'alerta_ia') {
    cor = dados.severidade === 'alto' ? T.red : T.yellow; icon = '🤖';
    titulo = dados.titulo;
    subtitulo = 'Alerta IA preditivo';
  } else if (tipo === 'exame') {
    cor = T.purple; icon = '🔬';
    titulo = dados.exame;
    subtitulo = dados.resultado;
  } else if (tipo === 'medicacao') {
    cor = T.tealDark; icon = '💊';
    titulo = `${dados.acao}: ${dados.medicamento}`;
    subtitulo = 'Alteração terapêutica';
  } else if (tipo === 'exacerbacao') {
    cor = T.red; icon = '⚠️';
    titulo = `Exacerbação ${dados.severidade}`;
    subtitulo = 'Evento clínico relevante';
  } else if (tipo === 'diagnostico') {
    cor = T.tealDark; icon = '🩺';
    titulo = 'Diagnóstico inicial';
    subtitulo = 'Início do percurso DPOC';
  }

  return (
    <View style={S.xba7053}>
      {/* Coluna esquerda: linha + bola */}
      <View style={S.x33da27}>
        <View style={{
          width: 36, height: 36, borderRadius: 18, backgroundColor: cor + '20',
          borderWidth: 2, borderColor: futura ? cor : 'transparent',
          alignItems: 'center', justifyContent: 'center', zIndex: 2,
        }}>
          <Text style={S.x563c7f}>{icon}</Text>
        </View>
        <View style={S.x49ae62} />
      </View>

      {/* Conteúdo */}
      <View style={S.x4ca248}>
        <View style={S.xa57794}>
          <Text style={S.xb5c39d}>{dataFmt}</Text>
          <Text style={S.xde2eb5}>• {horaFmt}</Text>
          {futura ? (
            <View style={S.x6c5341}>
              <Text style={S.x4f014f}>AGENDADA</Text>
            </View>
          ) : null}
        </View>
        <Card style={{ paddingVertical: 12, paddingHorizontal: 14, borderLeftWidth: 4, borderLeftColor: cor }}>
          {/* Badge de especialidade no topo, quando é consulta/exame com profissional */}
          {(tipo === 'consulta' || tipo === 'consulta_futura' || tipo === 'exame' || tipo === 'medicacao') && dados.profId ? (
            <View style={{
              flexDirection: 'row', alignItems: 'center',
              alignSelf: 'flex-start',
              backgroundColor: cor + '20',
              paddingHorizontal: 8, paddingVertical: 3, borderRadius: 6,
              marginBottom: 8,
            }}>
              <Text style={S.xf3a1ca}>{getProById(dados.profId)?.icon}</Text>
              <Text style={{ color: cor, fontSize: 10, fontWeight: '900', letterSpacing: 0.5 }}>
                {getProById(dados.profId)?.spec.toUpperCase()}
              </Text>
            </View>
          ) : null}

          <Text style={S.x3ca516}>{titulo}</Text>
          {subtitulo ? <Text style={S.x04586a}>{subtitulo}</Text> : null}
          {dados.notas ? (
            <Text style={S.xf31698}>
              "{dados.notas}"
            </Text>
          ) : null}
          {dados.descricao ? (
            <Text style={S.x307215}>
              {dados.descricao}
            </Text>
          ) : null}

          {/* Anexos */}
          {dados.anexos && dados.anexos.length > 0 ? (
            <View style={S.xe1a3f7}>
              <Text style={[S.label, { fontSize: 9, marginBottom: 6 }]}>📎 DOCUMENTAÇÃO</Text>
              {dados.anexos.map((a, ai) => (
                <TouchableOpacity key={ai} onPress={() => Alert.alert('Abrir documento', a.nome)} activeOpacity={0.7}
                  style={S.xad357b}>
                  <Text style={S.x88f31c}>{a.tipo === 'pdf' ? '📄' : '🖼️'}</Text>
                  <View style={S.xd2dc0a}>
                    <Text style={S.x08c8d1}>{a.nome}</Text>
                    <Text style={S.x0de9e0}>{a.tamanho}</Text>
                  </View>
                  <Text style={S.x760086}>›</Text>
                </TouchableOpacity>
              ))}
            </View>
          ) : null}

          {/* Botão adicionar documento (só em consultas, passadas) */}
          {(tipo === 'consulta' || tipo === 'exame' || tipo === 'exacerbacao') && !futura ? (
            <TouchableOpacity
              onPress={() => Alert.alert('Adicionar documento', 'Escolha um ficheiro do seu dispositivo para anexar a este registo.')}
              style={S.x143ac8}
              activeOpacity={0.7}
            >
              <Text style={S.xfdf478}>＋ Anexar documento</Text>
            </TouchableOpacity>
          ) : null}
        </Card>
      </View>
    </View>
  );
}

