function StatCol({ label, value, alert }) {
  return (
    <View style={S.xf254bd}>
      <Text style={S.x2ee2cd}>{label}</Text>
      <Text style={{ color: alert ? T.red : T.white, fontSize: 14, fontWeight: '800', marginTop: 2 }}>{value}</Text>
    </View>
  );
}

function riscoColor(r) {
  if (r === 'alto') return T.red;
  if (r === 'moderado') return T.yellow;
  return T.green;
}

