// AGENDAR CONSULTA - Profissional escolhe utente + especialista + data + hora
// ============================================================
function AgendarConsultaScreen({ nav, route, consultas, setConsultas, chatMensagens, setChatMensagens, userPro }) {
  // route pode ter utenteIdPre (se vier da ficha do utente)
  const utentePre = route?.utenteId;
  const [passo, setPasso] = useState(utentePre ? 1 : 0); // 0=utente, 1=especialista, 2=data/hora, 3=motivo
  const [utenteSel, setUtenteSel] = useState(utentePre ? UTENTES_MOCK.find(u => u.id === utentePre) : null);
  const [especialistaSel, setEspecialistaSel] = useState(null);
  const [dataSel, setDataSel] = useState(null);
  const [horaSel, setHoraSel] = useState(null);
  const [motivo, setMotivo] = useState('');

  // Gerar próximos 14 dias (apenas dias úteis)
  const proximosDias = [];
  for (let i = 1; i <= 21 && proximosDias.length < 14; i++) {
    const d = new Date();
    d.setDate(d.getDate() + i);
    if (d.getDay() !== 0 && d.getDay() !== 6) {
      proximosDias.push(d);
    }
  }

  const fmtData = (d) => d.toLocaleDateString('pt-PT', { day: '2-digit', month: 'short' });
  const fmtDataLong = (d) => d.toLocaleDateString('pt-PT', { weekday: 'long', day: '2-digit', month: 'long' });
  const isoDate = (d) => d.toISOString().split('T')[0];

  const confirmar = () => {
    if (!utenteSel || !especialistaSel || !dataSel || !horaSel) return;

    const novaConsulta = {
      id: 'c' + Date.now(),
      utenteId: utenteSel.id,
      utenteNome: utenteSel.nome,
      especialistaId: especialistaSel.id,
      data: isoDate(dataSel),
      hora: horaSel,
      motivo: motivo || 'Consulta de seguimento',
      estado: 'confirmada',
      marcadoPor: userPro?.nome || 'Profissional',
      timestamp: Date.now(),
    };

    setConsultas([...consultas, novaConsulta]);

    // Notificação automática no chat clínico do utente
    const notif = {
      id: 'sys' + Date.now(),
      tipo: 'sistema',
      autor: 'Sistema CarePath',
      texto: `📅 ${userPro?.nome || 'Profissional'} agendou consulta de ${especialistaSel.especialidade} para ${fmtData(dataSel)} às ${horaSel}.`,
      timestamp: Date.now(),
    };
    const chatUtente = chatMensagens[utenteSel.id] || [];
    setChatMensagens({ ...chatMensagens, [utenteSel.id]: [...chatUtente, notif] });

    Alert.alert(
      '✓ Consulta agendada',
      `${utenteSel.nome}\n${especialistaSel.nome}\n${fmtDataLong(dataSel)} às ${horaSel}\n\nA equipa foi notificada via chat clínico.`,
      [{ text: 'OK', onPress: () => nav('agendaPro') }]
    );
  };

  // PASSO 0: escolher utente
  if (passo === 0) {
    return (
      <SafeAreaView style={S.x8d5d23}>
        <Header title="Agendar consulta" onBack={() => nav('agendaPro')} />
        <ScrollView contentContainerStyle={S.xdc5e6d}>
          <View style={S.xc9a163}>
            {[0,1,2,3].map(i => (
              <View key={i} style={{
                flex: 1, height: 4, borderRadius: 2,
                backgroundColor: i <= passo ? T.teal : T.border2,
              }} />
            ))}
          </View>
          <Text style={[S.label, { marginBottom: 14 }]}>PASSO 1 DE 4 · ESCOLHER UTENTE</Text>
          {UTENTES_MOCK.map(u => (
            <TouchableOpacity key={u.id} onPress={() => { setUtenteSel(u); setPasso(1); }}
              style={S.xa9a55c}>
              <View style={S.xa8be2b}>
                <Text style={S.x34ab5c}>👤</Text>
              </View>
              <View style={S.xd2dc0a}>
                <Text style={S.x3ca516}>{u.nome}</Text>
                <Text style={S.x421c1c}>{u.idade}a · {u.gold} · {u.risco.toUpperCase()}</Text>
              </View>
              <Text style={S.xd90987}>›</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </SafeAreaView>
    );
  }

  // PASSO 1: escolher especialista
  if (passo === 1) {
    return (
      <SafeAreaView style={S.x8d5d23}>
        <Header title="Agendar consulta" onBack={() => utentePre ? nav('agendaPro') : setPasso(0)} />
        <ScrollView contentContainerStyle={S.xdc5e6d}>
          <View style={S.xc9a163}>
            {[0,1,2,3].map(i => (
              <View key={i} style={{
                flex: 1, height: 4, borderRadius: 2,
                backgroundColor: i <= passo ? T.teal : T.border2,
              }} />
            ))}
          </View>
          <Text style={[S.label, { marginBottom: 4 }]}>PASSO 2 DE 4</Text>
          <Text style={S.x0ec2b7}>
            Utente: <Text style={S.x2083d8}>{utenteSel.nome}</Text>
          </Text>
          <Text style={[S.label, { marginBottom: 14, marginTop: 12 }]}>ESCOLHER ESPECIALISTA</Text>

          {ESPECIALISTAS_MOCK.map(p => (
            <TouchableOpacity key={p.id} onPress={() => { setEspecialistaSel(p); setPasso(2); }}
              style={S.xa9a55c}>
              <View style={{
                width: 4, height: 44, backgroundColor: p.cor, borderRadius: 2, marginRight: 12,
              }} />
              <View style={S.xd2dc0a}>
                <Text style={S.x3ca516}>{p.nome}</Text>
                <Text style={{ color: p.cor, fontSize: 11, fontWeight: '700' }}>{p.especialidade}</Text>
                <Text style={S.x99dff6}>{p.local}</Text>
              </View>
              <Text style={S.xd90987}>›</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </SafeAreaView>
    );
  }

  // PASSO 2: data e hora
  if (passo === 2) {
    return (
      <SafeAreaView style={S.x8d5d23}>
        <Header title="Agendar consulta" onBack={() => setPasso(1)} />
        <ScrollView contentContainerStyle={S.xdc5e6d}>
          <View style={S.xc9a163}>
            {[0,1,2,3].map(i => (
              <View key={i} style={{
                flex: 1, height: 4, borderRadius: 2,
                backgroundColor: i <= passo ? T.teal : T.border2,
              }} />
            ))}
          </View>
          <Text style={[S.label, { marginBottom: 4 }]}>PASSO 3 DE 4 · DATA E HORA</Text>
          <Text style={S.x130f54}>
            {especialistaSel.nome} · <Text style={{ color: especialistaSel.cor, fontWeight: '700' }}>{especialistaSel.especialidade}</Text>
          </Text>

          <Text style={[S.label, { marginBottom: 8 }]}>DATA</Text>
          {/* Atalhos de agendamento rápido */}
          <View style={S.quickDateRow}>
            {[
              { lbl: '1 semana', dias: 7 },
              { lbl: '2 semanas', dias: 14 },
              { lbl: '1 mês', dias: 30 },
            ].map((atalho) => (
              <TouchableOpacity key={atalho.lbl} activeOpacity={0.75}
                accessibilityRole="button" accessibilityLabel={`Agendar daqui a ${atalho.lbl}`}
                onPress={() => {
                  const alvo = new Date();
                  alvo.setDate(alvo.getDate() + atalho.dias);
                  while (alvo.getDay() === 0 || alvo.getDay() === 6) alvo.setDate(alvo.getDate() + 1);
                  const match = proximosDias.find(d => isoDate(d) === isoDate(alvo)) || alvo;
                  setDataSel(match); setHoraSel(null);
                }}
                style={S.quickDateBtn}>
                <Text style={S.quickDateTxt}>+{atalho.lbl}</Text>
              </TouchableOpacity>
            ))}
          </View>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} style={S.xaa47df}>
            {proximosDias.map((d, i) => {
              const isSel = dataSel && dataSel.getTime() === d.getTime();
              return (
                <TouchableOpacity key={i} onPress={() => { setDataSel(d); setHoraSel(null); }}
                  style={{
                    width: 64, paddingVertical: 10, marginRight: 8,
                    borderRadius: 10, alignItems: 'center',
                    backgroundColor: isSel ? T.teal : T.card,
                    borderWidth: 1.5, borderColor: isSel ? T.teal : T.border2,
                  }}>
                  <Text style={{ color: isSel ? '#fff' : T.muted, fontSize: 10, fontWeight: '600' }}>
                    {d.toLocaleDateString('pt-PT', { weekday: 'short' }).toUpperCase().slice(0,3)}
                  </Text>
                  <Text style={{ color: isSel ? '#fff' : T.white, fontSize: 18, fontWeight: '800', marginTop: 2 }}>
                    {d.getDate()}
                  </Text>
                  <Text style={{ color: isSel ? '#fff' : T.muted, fontSize: 9 }}>
                    {d.toLocaleDateString('pt-PT', { month: 'short' })}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>

          {dataSel && (
            <>
              <Text style={[S.label, { marginBottom: 8 }]}>HORÁRIO DISPONÍVEL</Text>
              <View style={S.x1d91be}>
                {especialistaSel.horariosDisponiveis.map(h => {
                  const isSel = h === horaSel;
                  return (
                    <TouchableOpacity key={h} onPress={() => setHoraSel(h)}
                      style={{
                        paddingHorizontal: 16, paddingVertical: 10,
                        borderRadius: 8,
                        backgroundColor: isSel ? T.teal : T.card,
                        borderWidth: 1.5, borderColor: isSel ? T.teal : T.border2,
                      }}>
                      <Text style={{ color: isSel ? '#fff' : T.white, fontSize: 13, fontWeight: '700' }}>{h}</Text>
                    </TouchableOpacity>
                  );
                })}
              </View>

              {horaSel && (
                <PrimaryBtn label="Continuar" onPress={() => setPasso(3)} />
              )}
            </>
          )}
        </ScrollView>
      </SafeAreaView>
    );
  }

  // PASSO 3: motivo + confirmação
  return (
    <SafeAreaView style={S.x8d5d23}>
      <Header title="Confirmar agendamento" onBack={() => setPasso(2)} />
      <ScrollView contentContainerStyle={S.xdc5e6d}>
        <View style={S.xc9a163}>
          {[0,1,2,3].map(i => (
            <View key={i} style={{
              flex: 1, height: 4, borderRadius: 2,
              backgroundColor: i <= passo ? T.teal : T.border2,
            }} />
          ))}
        </View>
        <Text style={[S.label, { marginBottom: 14 }]}>PASSO 4 DE 4 · REVER E CONFIRMAR</Text>

        <Card style={S.x64b117}>
          <Text style={[S.label, { marginBottom: 8 }]}>UTENTE</Text>
          <Text style={S.x73c7d6}>{utenteSel.nome}</Text>
          <Text style={S.xa87ee8}>{utenteSel.idade}a · {utenteSel.gold}</Text>
        </Card>

        <Card style={S.x64b117}>
          <Text style={[S.label, { marginBottom: 8 }]}>ESPECIALISTA</Text>
          <View style={S.x39bee2}>
            <View style={{ width: 4, height: 36, backgroundColor: especialistaSel.cor, borderRadius: 2, marginRight: 10 }} />
            <View style={S.xd2dc0a}>
              <Text style={S.x3ca516}>{especialistaSel.nome}</Text>
              <Text style={{ color: especialistaSel.cor, fontSize: 11, fontWeight: '700' }}>{especialistaSel.especialidade}</Text>
              <Text style={S.x41a694}>{especialistaSel.local}</Text>
            </View>
          </View>
        </Card>

        <Card style={S.x64b117}>
          <Text style={[S.label, { marginBottom: 8 }]}>QUANDO</Text>
          <Text style={S.xfd6b0b}>{fmtDataLong(dataSel)}</Text>
          <Text style={S.x8da9b2}>{horaSel}</Text>
        </Card>

        <Card style={S.xad064e}>
          <Text style={[S.label, { marginBottom: 8 }]}>MOTIVO DA CONSULTA</Text>
          <TextInput
            value={motivo}
            onChangeText={setMotivo}
            placeholder="Ex: Revisão pós-exacerbação"
            placeholderTextColor={T.muted}
            multiline
            style={S.x9d85d8}
          />
        </Card>

        <View style={S.x8855c5}>
          <Text style={S.x88f31c}>💬</Text>
          <Text style={S.xf920dd}>
            A equipa multidisciplinar do utente será notificada automaticamente via chat clínico.
          </Text>
        </View>

        <PrimaryBtn label="✓ Confirmar agendamento" onPress={confirmar} />
      </ScrollView>
    </SafeAreaView>
  );
}

// ============================================================
// CHAT CLÍNICO - mensagens da equipa multidisciplinar por caso
// ============================================================
function ChatClinicoScreen({ nav, route, chatMensagens, setChatMensagens, userPro }) {
  const utenteId = route?.utenteId || 'u1';
  const utente = UTENTES_MOCK.find(u => u.id === utenteId);
  const mensagens = chatMensagens[utenteId] || [];

  const [novoTexto, setNovoTexto] = useState('');

  const enviar = () => {
    if (!novoTexto.trim()) return;
    const novaMsg = {
      id: 'm' + Date.now(),
      tipo: 'mensagem',
      autorId: userPro?.id || 'p1',
      autor: userPro?.nome || 'Dra. Helena Marques',
      papel: userPro?.especialidade || 'Pneumologia',
      texto: novoTexto.trim(),
      timestamp: Date.now(),
    };
    setChatMensagens({ ...chatMensagens, [utenteId]: [...mensagens, novaMsg] });
    setNovoTexto('');
  };

  const fmtTempo = (ts) => {
    const diff = Date.now() - ts;
    const horas = Math.floor(diff / 3600000);
    const dias = Math.floor(horas / 24);
    if (dias > 0) return `há ${dias}d`;
    if (horas > 0) return `há ${horas}h`;
    const mins = Math.floor(diff / 60000);
    if (mins > 0) return `há ${mins}min`;
    return 'agora';
  };

  return (
    <SafeAreaView style={S.x8d5d23}>
      <View style={{ backgroundColor: T.tealDark, paddingTop: Platform.OS === 'android' ? 24 : 12, paddingBottom: 14, paddingHorizontal: 16 }}>
        <View style={S.xe7592d}>
          <TouchableOpacity onPress={() => nav('utenteFicha', { utenteId })} style={S.x6566f1}>
            <Text style={S.x82ffef}>‹</Text>
          </TouchableOpacity>
          <View style={S.xd2dc0a}>
            <Text style={S.x2e252c}>CASO CLÍNICO · CHAT DE EQUIPA</Text>
            <Text style={S.x3414e9}>{utente?.nome}</Text>
            <Text style={S.x2e252c}>
              {utente?.gold} · {utente?.usf} · {mensagens.length} mensagens
            </Text>
          </View>
        </View>
      </View>

      <ScrollView style={S.xd2dc0a} contentContainerStyle={S.xe18fd7}>
        {mensagens.length === 0 && (
          <View style={S.x751be2}>
            <Text style={S.x1137a6}>💬</Text>
            <Text style={S.xdbab75}>
              Nenhuma mensagem ainda.{'\n'}Seja o primeiro a comentar este caso.
            </Text>
          </View>
        )}

        {mensagens.map((m, i) => {
          if (m.tipo === 'sistema') {
            return (
              <View key={m.id} style={S.x85045b}>
                <Text style={S.xf4c428}>
                  {m.autor.toUpperCase()} · {fmtTempo(m.timestamp)}
                </Text>
                <Text style={S.x30c3b7}>{m.texto}</Text>
              </View>
            );
          }
          // mensagem normal de profissional
          const isMine = m.autorId === (userPro?.id || 'p1');
          return (
            <View key={m.id} style={{
              alignSelf: isMine ? 'flex-end' : 'flex-start',
              maxWidth: '85%',
              marginBottom: 10,
            }}>
              {!isMine && (
                <Text style={S.x81709b}>
                  {m.autor.toUpperCase()} · {m.papel}
                </Text>
              )}
              <View style={{
                backgroundColor: isMine ? T.teal : T.card,
                padding: 10, borderRadius: 12,
                borderBottomRightRadius: isMine ? 2 : 12,
                borderBottomLeftRadius: isMine ? 12 : 2,
                shadowColor: '#1F2937', shadowOpacity: 0.04, shadowRadius: 4, shadowOffset: { width: 0, height: 1 }, elevation: 1,
              }}>
                <Text style={{ color: isMine ? '#fff' : T.white, fontSize: 13, lineHeight: 18 }}>{m.texto}</Text>
              </View>
              <Text style={{
                color: T.muted, fontSize: 9, marginTop: 2,
                textAlign: isMine ? 'right' : 'left', marginHorizontal: 4,
              }}>{fmtTempo(m.timestamp)}</Text>
            </View>
          );
        })}
      </ScrollView>

      <View style={S.x29eaa5}>
        <TextInput
          value={novoTexto}
          onChangeText={setNovoTexto}
          placeholder="Comentar este caso..."
          placeholderTextColor={T.muted}
          multiline
          style={S.x00a6ca}
        />
        <TouchableOpacity onPress={enviar} disabled={!novoTexto.trim()}
          style={{
            width: 38, height: 38, borderRadius: 19,
            backgroundColor: novoTexto.trim() ? T.teal : T.muted,
            alignItems: 'center', justifyContent: 'center',
          }}>
          <Text style={S.xee1d4b}>↑</Text>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
}

function AgendaProScreen({ nav, consultas }) {
  // Agrupa CONSULTAS_AGENDADAS por dia
  const grupos = useMemo(() => {
    const map = {};
    consultas.forEach(c => {
      const key = c.data;
      if (!map[key]) map[key] = [];
      map[key].push(c);
    });
    // Ordenar consultas dentro de cada dia por hora
    Object.keys(map).forEach(k => map[k].sort((a, b) => a.hora.localeCompare(b.hora)));
    return Object.keys(map).sort().map(k => ({
      data: k,
      consultas: map[k],
    }));
  }, [consultas]);

  const labelDia = (dataStr) => {
    const d = new Date(dataStr + 'T00:00:00');
    const hoje = new Date(); hoje.setHours(0,0,0,0);
    const amanha = new Date(hoje); amanha.setDate(amanha.getDate() + 1);
    if (d.getTime() === hoje.getTime()) return 'HOJE';
    if (d.getTime() === amanha.getTime()) return 'AMANHÃ';
    return d.toLocaleDateString('pt-PT', { weekday: 'long', day: '2-digit', month: 'long' }).toUpperCase();
  };

  const hoje = new Date().toISOString().split('T')[0];
  const totalHoje = grupos.find(g => g.data === hoje)?.consultas.length || 0;
  const totalSemana = grupos.reduce((sum, g) => sum + g.consultas.length, 0);

  return (
    <View style={S.x8d5d23}>
      <View style={{ padding: 20, paddingTop: Platform.OS === 'android' ? 24 : 12, paddingBottom: 12 }}>
        <Text style={S.x77752b}>Agenda da equipa</Text>
        <Text style={S.xe8ab22}>Próximas consultas</Text>
      </View>

      {/* Resumo */}
      <View style={S.xf07243}>
        <Card style={S.x7029fc}>
          <Text style={S.xf55a28}>HOJE</Text>
          <Text style={S.xe9d73f}>{totalHoje}</Text>
          <Text style={S.x41a694}>consultas</Text>
        </Card>
        <Card style={S.x7029fc}>
          <Text style={S.xf55a28}>PRÓXIMOS DIAS</Text>
          <Text style={S.xeee6a2}>{totalSemana}</Text>
          <Text style={S.x41a694}>marcadas</Text>
        </Card>
        <Card style={S.x7029fc}>
          <Text style={S.xf55a28}>EQUIPA</Text>
          <Text style={S.xbc1e07}>
            {ESPECIALISTAS_MOCK.length}
          </Text>
          <Text style={S.x41a694}>especialistas</Text>
        </Card>
      </View>

      <ScrollView contentContainerStyle={S.x5f905a}>
        {grupos.length === 0 && (
          <View style={S.x751be2}>
            <Text style={S.x1137a6}>📅</Text>
            <Text style={S.xdbab75}>
              Nenhuma consulta agendada.{'\n'}Use o botão + para agendar uma nova.
            </Text>
          </View>
        )}

        {grupos.map((g, gi) => (
          <View key={g.data} style={S.xaf4f2c}>
            <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: gi === 0 ? 4 : 12, marginBottom: 10 }}>
              <View style={{ width: 6, height: 6, borderRadius: 3, backgroundColor: gi === 0 ? T.teal : T.muted, marginRight: 8 }} />
              <Text style={{ color: gi === 0 ? T.teal : T.muted, fontSize: 11, fontWeight: '800', letterSpacing: 1.2 }}>
                {labelDia(g.data)}
              </Text>
              <View style={S.x8e9cfc} />
            </View>
            {g.consultas.map(c => {
              const u = UTENTES_MOCK.find(x => x.id === c.utenteId);
              const esp = ESPECIALISTAS_MOCK.find(x => x.id === c.especialistaId);
              return (
                <TouchableOpacity key={c.id} onPress={() => nav('utenteFicha', { utenteId: c.utenteId })} activeOpacity={0.75}
                  style={S.xa4a170}>
                  {/* Hora */}
                  <View style={S.xa127e5}>
                    <Text style={S.xaabbf9}>{c.hora}</Text>
                  </View>

                  {/* Cartão */}
                  <Card style={{ flex: 1, paddingVertical: 12, paddingHorizontal: 14, borderLeftWidth: 3, borderLeftColor: esp?.cor || T.teal }}>
                    <View style={S.x3aec73}>
                      <View style={S.x4a9ebd}>
                        <Text style={S.xd28d68}>
                          {u?.nome.split(' ').map(n => n[0]).join('').substring(0,2)}
                        </Text>
                      </View>
                      <View style={S.xd2dc0a}>
                        <Text style={S.x3ca516}>{c.utenteNome}</Text>
                        <Text style={{ color: esp?.cor || T.teal, fontSize: 11, fontWeight: '700', marginTop: 2 }}>
                          {esp?.especialidade}
                        </Text>
                        <Text style={S.xc59203} numberOfLines={2}>
                          {c.motivo}
                        </Text>
                      </View>
                      {u?.risco === 'alto' && (
                        <Text style={S.x88061f}>⚠</Text>
                      )}
                    </View>
                  </Card>
                </TouchableOpacity>
              );
            })}
          </View>
        ))}
      </ScrollView>

      {/* FAB - Botão flutuante "Agendar nova" */}
      <TouchableOpacity onPress={() => nav('agendarConsulta')} activeOpacity={0.85}
        style={S.x016f4a}>
        <Text style={S.x2cb18a}>+</Text>
        <Text style={S.xaa4443}>AGENDAR</Text>
      </TouchableOpacity>
    </View>
  );
}

