// ============================================================
// IA - Cálculo de risco (DPOC)
// ============================================================
function calcularRisco(r) {
  if (!r) return { nivel: 'baixo', cor: T.green, titulo: 'Sem dados ainda', mensagem: 'Registe os seus sinais para começar.', fatores: [], gold: null, pontos: 0 };

  let pontos = 0;
  const fatores = []; // explicabilidade: porquê deste nível

  // Oxigenação (SpO2)
  if (r.spo2 != null) {
    if (r.spo2 < 92)      { pontos += 3; fatores.push(`Oxigénio baixo (SpO₂ ${r.spo2}%)`); }
    else if (r.spo2 < 95) { pontos += 1; fatores.push(`Oxigénio no limite (SpO₂ ${r.spo2}%)`); }
  }
  // Frequência cardíaca
  if (r.fc != null) {
    if (r.fc > 110)     { pontos += 2; fatores.push(`Pulso acelerado (${r.fc} bpm)`); }
    else if (r.fc > 100){ pontos += 1; fatores.push(`Pulso um pouco elevado (${r.fc} bpm)`); }
  }
  // Falta de ar (mMRC)
  if (r.mmrc != null) {
    if (r.mmrc >= 4)      { pontos += 3; fatores.push('Falta de ar grave (mMRC 4)'); }
    else if (r.mmrc >= 3) { pontos += 2; fatores.push('Falta de ar acentuada (mMRC 3)'); }
    else if (r.mmrc >= 2) { pontos += 1; fatores.push('Falta de ar moderada (mMRC 2)'); }
  }
  // Sintomas (CAT)
  if (r.cat != null) {
    if (r.cat >= 25)      { pontos += 3; fatores.push(`Sintomas muito intensos (CAT ${r.cat})`); }
    else if (r.cat >= 20) { pontos += 2; fatores.push(`Sintomas elevados (CAT ${r.cat})`); }
    else if (r.cat >= 10) { pontos += 1; fatores.push(`Sintomas moderados (CAT ${r.cat})`); }
  }
  // Tensão arterial
  if (r.ta_sis != null && (r.ta_sis > 160 || r.ta_sis < 100)) {
    pontos += 1; fatores.push(`Tensão fora do habitual (${r.ta_sis} mmHg)`);
  }
  // Histórico de exacerbações (risco de fundo)
  const exac = r.exacerbacoesAno || 0;
  if (exac >= 2 || r.hospitalizadoAno) {
    pontos += 2; fatores.push(`Historial de exacerbações (${exac} no último ano)`);
  }

  // Classificação GOLD ABE (avaliação de fundo: sintomas + risco de exacerbação)
  const muitosSintomas = (r.mmrc >= 2) || (r.cat >= 10);
  const altoRiscoExac  = (exac >= 2) || r.hospitalizadoAno;
  const gold = altoRiscoExac ? 'E' : (muitosSintomas ? 'B' : 'A');

  if (pontos >= 7) return {
    nivel: 'alto', cor: T.red,
    titulo: 'Risco elevado de exacerbação',
    mensagem: 'Os seus indicadores sugerem deterioração. Contacte a sua equipa hoje.',
    fatores, gold, pontos,
  };
  if (pontos >= 3) return {
    nivel: 'moderado', cor: T.yellow,
    titulo: 'Sinais a vigiar',
    mensagem: 'Alguns sintomas em progressão. Mantenha a medicação e contacte se piorar.',
    fatores, gold, pontos,
  };
  return {
    nivel: 'baixo', cor: T.green,
    titulo: 'Tudo dentro do esperado',
    mensagem: 'Os seus indicadores estão estáveis. Continue o registo diário.',
    fatores: fatores.length ? fatores : ['Indicadores estáveis'], gold, pontos,
  };
}

// ============================================================
// ============================================================
// INTEROPERABILIDADE — Demonstração de exportação FHIR
// Mostra que os dados do utente PODEM ser estruturados no formato
// padrão (HL7 FHIR) usado pelo SNS para troca entre sistemas.
// (Demonstração — a troca real exige backend e servidor FHIR.)
// ============================================================
function gerarFHIR(user, ultimo) {
  const obs = (codigo, nome, valor, unidade) => ({
    resourceType: 'Observation', status: 'final',
    code: { coding: [{ system: 'http://loinc.org', code: codigo, display: nome }] },
    subject: { display: user?.nome || 'Utente' },
    valueQuantity: { value: valor, unit: unidade },
    effectiveDateTime: ultimo?.ts || new Date().toISOString(),
  });
  return {
    resourceType: 'Bundle', type: 'collection',
    entry: [
      { resource: { resourceType: 'Patient', name: [{ text: user?.nome || 'Utente' }],
        identifier: [{ system: 'SNS', value: user?.email || '—' }] } },
      { resource: obs('2708-6', 'Saturação O₂', ultimo?.spo2, '%') },
      { resource: obs('8867-4', 'Frequência cardíaca', ultimo?.fc, 'bpm') },
      { resource: obs('8480-6', 'Tensão sistólica', ultimo?.ta_sis, 'mmHg') },
    ],
  };
}

function FHIRScreen({ nav, user, registos }) {
  const ultimo = (registos || [])[0];
  const bundle = gerarFHIR(user, ultimo);
  const json = JSON.stringify(bundle, null, 2);
  return (
    <SafeAreaView style={S.flexBg}>
      <Header title="Interoperabilidade" onBack={() => nav('perfilUtente')} />
      <ScrollView contentContainerStyle={S.formScroll}>
        <View style={S.fhirIntro}>
          <Text style={S.fhirTitulo}>🔗 Dados em formato FHIR</Text>
          <Text style={S.fhirTxt}>
            O CarePath estrutura os seus dados no formato HL7 FHIR — o padrão usado pelo SNS para trocar informação entre sistemas (ex.: SClínico). Isto demonstra que os dados podem ser partilhados com segurança e de forma compatível.
          </Text>
        </View>
        <Text style={[S.label, S.mb12]}>EXEMPLO (Bundle FHIR)</Text>
        <View style={S.fhirCode}>
          <Text style={S.fhirCodeTxt}>{json}</Text>
        </View>
        <Text style={S.assistDisclaimer}>
          Demonstração técnica. A troca real com sistemas do SNS exige um servidor FHIR e autorização — fora do âmbito deste protótipo.
        </Text>
      </ScrollView>
    </SafeAreaView>
  );
}

