// DETEÇÃO DE INCUMPRIMENTO TERAPÊUTICO (adesão à medicação)
// Analisa a medicação regular (exclui SOS) e sinaliza o que falta tomar.
// ============================================================
function avaliarAdesao(medicacao) {
  const regulares = (medicacao || []).filter(m => m.horario !== 'SOS');
  const tomados = regulares.filter(m => m.tomadoHoje).length;
  const total = regulares.length;
  const emFalta = total - tomados;
  return { tomados, total, emFalta, completo: total > 0 && emFalta === 0 };
}

// ============================================================
// MOTOR DE DECISÃO DA AGENDA INTELIGENTE
// Recebe o risco e DECIDE como agir na agenda, com níveis de
// autonomia e travas de segurança (auditável para RGPD).
// ============================================================

// Configuração ajustável pela equipa clínica (travas de segurança)
const MOTOR_CONFIG = {
  maxDiasAntecipacaoAuto: 7,    // nunca antecipar > 7 dias de forma automática
  diasRiscoAlto: 2,             // risco alto → consulta em ~2 dias
  diasRiscoModerado: 7,         // risco moderado → sugerir em ~7 dias
};

// Próximo dia útil a partir de hoje + N dias
function diaUtilDaqui(dias) {
  const d = new Date();
  d.setDate(d.getDate() + dias);
  while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() + 1);
  return d;
}

// Decide a ação da agenda a partir do risco:
//  - 'automatico': antecipa a consulta automaticamente (dentro da trava de segurança)
//  - 'sugerir':    propõe antecipação, mas requer confirmação do profissional
//  - 'manter':     não altera a agenda
function decidirAgenda(risco, user) {
  const base = {
    utenteId: user?.id || 'u1',
    utenteNome: user?.nome || 'Utente',
    especialistaId: 'p2',
  };
  const fmt = (d) => d.toLocaleDateString('pt-PT');
  const iso = (d) => d.toISOString().split('T')[0];

  if (risco.nivel === 'alto') {
    const data = diaUtilDaqui(MOTOR_CONFIG.diasRiscoAlto);
    return {
      acao: 'automatico',
      titulo: 'Consulta antecipada automaticamente',
      justificacao: `Risco elevado detetado na triagem. Consulta antecipada para ${fmt(data)}, dentro do limite de segurança de ${MOTOR_CONFIG.maxDiasAntecipacaoAuto} dias. A equipa foi notificada.`,
      consulta: {
        ...base, id: 'auto_' + Date.now(), data: iso(data), hora: '09:00',
        motivo: 'Antecipada · risco elevado (triagem IA)',
        estado: 'pendente', marcadoPor: 'Agenda Inteligente',
        timestamp: Date.now(), prioridade: 'alta',
      },
    };
  }
  if (risco.nivel === 'moderado') {
    const data = diaUtilDaqui(MOTOR_CONFIG.diasRiscoModerado);
    return {
      acao: 'sugerir',
      titulo: 'Sugestão de antecipação',
      justificacao: `Sinais a vigiar. O sistema sugere uma consulta para ${fmt(data)}. Requer confirmação do profissional antes de marcar.`,
      consulta: {
        ...base, id: 'sug_' + Date.now(), data: iso(data), hora: '11:00',
        motivo: 'Sugerida · sinais a vigiar (triagem IA)',
        estado: 'sugerida', marcadoPor: 'Agenda Inteligente (a confirmar)',
        timestamp: Date.now(), prioridade: 'media',
      },
    };
  }
  return {
    acao: 'manter',
    titulo: 'Agenda mantida',
    justificacao: 'Indicadores estáveis. Não é necessário antecipar consultas.',
    consulta: null,
  };
}

// ============================================================
// APP ROOT
// ============================================================
export default function App() {
  const [showSplash, setShowSplash] = useState(true);
  const [screen, setScreen] = useState('welcome');
  const [user, setUser] = useState(null);
  const [utenteSel, setUtenteSel] = useState(null);
  const [routeParams, setRouteParams] = useState(null);

  // Estado clínico do utente
  const [registos, setRegistos] = useState([
    { spo2: 94, fc: 82, ta_sis: 132, ta_dia: 78, peso: 72, mmrc: 2, cat: 14, exacerbacoesAno: 1, ts: new Date(Date.now() - 86400000).toISOString() },
  ]);
  const [sintomas, setSintomas] = useState([]);
  const [medicacao, setMedicacao] = useState([
    { nome: 'Salbutamol (Ventilan)', dose: '100 mcg', horario: 'SOS', tomadoHoje: true },
    { nome: 'Formoterol+Budesonida', dose: '160/4.5 mcg', horario: '2x/dia', tomadoHoje: false },
    { nome: 'Tiotrópio (Spiriva)',   dose: '18 mcg', horario: '1x/dia', tomadoHoje: true },
  ]);

  // Estado de equipa multidisciplinar - consultas e chat clínico
  const [consultas, setConsultas] = useState(CONSULTAS_AGENDADAS_INIT);
  const [chatMensagens, setChatMensagens] = useState(MENSAGENS_CHAT_INIT);

  // Persistência: carregar os dados guardados no telemóvel ao arrancar
  useEffect(() => {
    (async () => {
      try {
        const r = await AsyncStorage.getItem('carepath_registos');
        if (r) setRegistos(JSON.parse(r));
        const s = await AsyncStorage.getItem('carepath_sintomas');
        if (s) setSintomas(JSON.parse(s));
        const m = await AsyncStorage.getItem('carepath_medicacao');
        if (m) setMedicacao(JSON.parse(m));
      } catch (e) { /* primeira utilização ou sem dados guardados */ }
    })();
  }, []);

  // Persistência: guardar sempre que os dados do utente mudam
  useEffect(() => { AsyncStorage.setItem('carepath_registos', JSON.stringify(registos)).catch(() => {}); }, [registos]);
  useEffect(() => { AsyncStorage.setItem('carepath_sintomas', JSON.stringify(sintomas)).catch(() => {}); }, [sintomas]);
  useEffect(() => { AsyncStorage.setItem('carepath_medicacao', JSON.stringify(medicacao)).catch(() => {}); }, [medicacao]);

  const nav = (s, payload) => {
    if (payload && s === 'utente') setUtenteSel(payload);
    if (payload && s === 'ficha')  setUtenteSel(payload);
    // Para rotas com payload genérico (agendarConsulta, chatClinico, utenteFicha)
    if (payload && (s === 'agendarConsulta' || s === 'chatClinico' || s === 'utenteFicha')) {
      setRouteParams(payload);
      // utenteFicha: também carregar o utente
      if (s === 'utenteFicha') {
        const u = UTENTES_MOCK.find(x => x.id === payload.utenteId);
        if (u) setUtenteSel(u);
      }
    }
    setScreen(s);
  };
  // Quando o utente entra, atribuímos-lhe a ficha clínica completa (mock: Maria Santos)
  const onLogin = (u) => {
    if (u.tipo === 'profissional') {
      setUser(u);
      setScreen('homePro');
      return;
    }
    // utente e cuidador veem a vista do utente (dados da pessoa acompanhada)
    const enriched = {
      ...UTENTES_MOCK[0],
      email: u.email,
      tipo: u.tipo,
      nome: UTENTES_MOCK[0].nome,            // nome do utente acompanhado
      cuidadorNome: u.tipo === 'cuidador' ? u.nome : null,
    };
    setUser(enriched);
    setScreen('home');
  };
  const onLogout = () => { setUser(null); setUtenteSel(null); setScreen('welcome'); };

  // Trocar entre modo utente <-> profissional sem fazer logout
  const onSwitchMode = () => {
    if (!user) return;
    const novoTipo = user.tipo === 'profissional' ? 'utente' : 'profissional';
    if (novoTipo === 'profissional') {
      setUser({ email: user.email, nome: 'Dra. Helena Marques', tipo: 'profissional' });
    } else {
      const u = user.email.split('@')[0];
      setUser({ ...UTENTES_MOCK[0], email: user.email, nome: u, tipo: 'utente' });
    }
    setUtenteSel(null);
    setScreen(novoTipo === 'profissional' ? 'homePro' : 'home');
  };

  // Trocar de profissional (alternar entre os 6 papéis da equipa)
  const onTrocarPro = (pro) => {
    setUser({
      email: user.email,
      nome: pro.nome,
      especialidade: pro.spec,
      tipo: 'profissional',
    });
    Alert.alert('Perfil trocado', `Agora a operar como ${pro.nome} · ${pro.spec}`);
  };

  // Tabs com navbar (utente e profissional)
  const TABS_UTENTE = ['home','historico','equipa','perfil'];
  const TABS_PRO    = ['homePro','agendaPro','historicoPro','perfilPro'];
  const isPro = user?.tipo === 'profissional';
  const showNavBarUtente = user && !isPro && TABS_UTENTE.includes(screen);
  const showNavBarPro    = user && isPro && TABS_PRO.includes(screen);

  let content;
  if (!user) {
    if (screen === 'login') content = <LoginScreen nav={nav} onLogin={onLogin} />;
    else if (screen === 'register') content = <RegisterScreen nav={nav} onLogin={onLogin} />;
    else content = <WelcomeScreen nav={nav} />;
  } else if (isPro) {
    // userPro: o profissional atual (mock = Dra. Helena Marques)
    const userPro = { ...user, id: 'p1', especialidade: 'Pneumologia' };
    // Vista profissional
    switch (screen) {
      case 'homePro':      content = <HomeProScreen user={user} nav={nav} />; break;
      case 'agendaPro':    content = <AgendaProScreen nav={nav} consultas={consultas} />; break;
      case 'historicoPro': content = <HistoricoProScreen nav={nav} />; break;
      case 'modelo':       content = <ModeloScreen nav={nav} />; break;
      case 'utente':       content = <UtenteFichaScreen nav={nav} utente={utenteSel} />; break;
      case 'utenteFicha':  content = <UtenteFichaScreen nav={nav} utente={utenteSel || UTENTES_MOCK[0]} />; break;
      case 'ficha':        content = <FichaUtenteScreen nav={nav} utente={utenteSel || UTENTES_MOCK[0]} voltarPara="utente" />; break;
      case 'agendarConsulta':
        content = <AgendarConsultaScreen
                    nav={nav} route={routeParams}
                    consultas={consultas} setConsultas={setConsultas}
                    chatMensagens={chatMensagens} setChatMensagens={setChatMensagens}
                    userPro={userPro} />;
        break;
      case 'chatClinico':
        content = <ChatClinicoScreen
                    nav={nav} route={routeParams}
                    chatMensagens={chatMensagens} setChatMensagens={setChatMensagens}
                    userPro={userPro} />;
        break;
      case 'perfilPro':    content = <PerfilProScreen user={user} nav={nav} onLogout={onLogout} onSwitchMode={onSwitchMode} onTrocarPro={onTrocarPro} />; break;
      case 'integracao':   content = <IntegracaoScreen nav={nav} />; break;
      case 'impacto':      content = <ImpactoScreen nav={nav} />; break;
      case 'notificacoes': content = <NotificacoesScreen nav={nav} />; break;
      case 'dashboardEquipa': content = <DashboardEquipaScreen nav={nav} />; break;
      default:             content = <HomeProScreen user={user} nav={nav} />;
    }
  } else {
    // Vista utente
    switch (screen) {
      case 'home':       content = <HomeUtenteScreen user={user} nav={nav} registos={registos} medicacao={medicacao} />; break;
      case 'registo':    content = <RegistoVitaisScreen nav={nav} registos={registos} setRegistos={setRegistos} />; break;
      case 'escalas':    content = <EscalasScreen nav={nav} registos={registos} setRegistos={setRegistos} />; break;
      case 'medicacao':  content = <MedicacaoScreen nav={nav} medicacao={medicacao} setMedicacao={setMedicacao} />; break;
      case 'sintomas':   content = <SintomasScreen nav={nav} sintomas={sintomas} setSintomas={setSintomas} />; break;
      case 'triagem':    content = <TriagemIAScreen nav={nav} user={user} registos={registos} consultas={consultas} setConsultas={setConsultas} />; break;
      case 'assistente': content = <AssistenteScreen nav={nav} user={user} consultas={consultas} setConsultas={setConsultas} />; break;
      case 'pedirConsulta': content = <PedirConsultaScreen nav={nav} user={user} consultas={consultas} setConsultas={setConsultas} chatMensagens={chatMensagens} setChatMensagens={setChatMensagens} />; break;
      case 'plano':      content = <PlanoScreen nav={nav} medicacao={medicacao} />; break;
      case 'percurso':   content = <PercursoScreen nav={nav} />; break;
      case 'educacao':   content = <EducacaoScreen nav={nav} />; break;
      case 'fhir':       content = <FHIRScreen nav={nav} user={user} registos={registos} />; break;
      case 'mcdts':      content = <MCDTsScreen nav={nav} />; break;
      case 'telemonitor':content = <TelemonitorScreen nav={nav} registos={registos} />; break;
      case 'historico':  content = <HistoricoScreen nav={nav} registos={registos} sintomas={sintomas} />; break;
      case 'equipa':     content = <EquipaScreen nav={nav} />; break;
      case 'ficha':      content = <FichaUtenteScreen nav={nav} utente={user} voltarPara="perfil" />; break;
      case 'perfil':     content = <PerfilUtenteScreen user={user} nav={nav} onLogout={onLogout} onSwitchMode={onSwitchMode} />; break;
      default:           content = <HomeUtenteScreen user={user} nav={nav} registos={registos} />;
    }
  }

  return (
    <View style={S.x8d5d23}>
      <StatusBar barStyle="dark-content" backgroundColor={T.bg} />
      {showSplash ? (
        <SplashScreen onFinish={() => setShowSplash(false)} />
      ) : (
        <>
          <KeyboardAvoidingView
            style={S.xd2dc0a}
            behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
            {content}
          </KeyboardAvoidingView>
          {showNavBarUtente ? <NavBarUtente current={screen} onNav={nav} /> : null}
          {showNavBarPro    ? <NavBarPro    current={screen} onNav={nav} /> : null}
        </>
      )}
    </View>
  );
}

